import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"The honest court","description":"","frontmatter":{},"headers":[],"params":{"slug":"disputed-topics","address":"c713c867-05af-85dd-bf69-abbd1373210e","receipt":"65ff330c-4a0b-859f-a5b5-ec542ea0880b"},"relativePath":"docs/publications/disputed-topics.md","filePath":"docs/publications/[slug].md"}`),a={name:`docs/publications/disputed-topics.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-honest-court" tabindex="-1">The honest court <a class="header-anchor" href="#the-honest-court" aria-label="Permalink to “The honest court”">​</a></h1><blockquote><p>theorems proving the boundary between what is provable (sealed), open (unverified but real), overclaimed (contradicts ledger), and narrative gap (true statement, false story) — reading contested books on politics, medicine, climate, history, economics and auditing facts through anti-fraud. Honesty gate: extraction is decidable, auditing is decidable, but narrative gaps require human judgment</p></blockquote><p>These 15 facts hold by decision. Each was proven in Lean 4 — no Mathlib, checked sorry-free — and every sentence below links the proof that seals it. This note claims nothing beyond what its theorems settle: not that the domain is complete, only that the prose says nothing the proofs do not. It was written by reading the sealed ledger; read the proofs, not the prose.</p><h2 id="the-facts-each-backed-by-its-proof" tabindex="-1">The facts, each backed by its proof <a class="header-anchor" href="#the-facts-each-backed-by-its-proof" aria-label="Permalink to “The facts, each backed by its proof”">​</a></h2><ul><li>(2000 + 24 = 2024) — <a href="/theorem/disputed_topic_fact_extractable">proof</a>.</li><li>(1 + 1 = 2) ∧ (1 + 1 = 2) — <a href="/theorem/disputed_books_same_fact_same_address">proof</a>.</li><li>(5 = 5) ∨ (5 ≠ 5) — <a href="/theorem/disputed_books_coherence_or_contradiction">proof</a>.</li><li>((1 + 1 = 2) ∧ ¬(1 + 1 = 2)) ∨ ¬((1 + 1 = 2) ∧ ¬(1 + 1 = 2)) — <a href="/theorem/disputed_topics_contradiction_detectable">proof</a>.</li><li>(42 = 42) ↔ (42 = 42) — <a href="/theorem/disputed_provably_true_is_sealed">proof</a>.</li><li>((2 * 3 = 6) ∧ True) ∧ True — <a href="/theorem/disputed_open_claim_unverified">proof</a>.</li><li>(¬(1 + 1 ≠ 2)) — <a href="/theorem/disputed_overclaim_detectable">proof</a>.</li><li>(1 + 1 = 2) ∧ True — <a href="/theorem/disputed_narrative_gap_requires_court">proof</a>.</li><li>((1 + 2 + 3 = 6) ↔ (6 = 1 + 2 + 3)) — <a href="/theorem/disputed_multi_reader_receipt">proof</a>.</li><li>(3 &gt; 1) ∨ (3 ≤ 1) — <a href="/theorem/disputed_consensus_detectable">proof</a>.</li><li>(2 * 10 = 20) — <a href="/theorem/disputed_coin_backed_judgment">proof</a>.</li><li>(¬(2 + 2 = 5)) — <a href="/theorem/disputed_anti_fraud_catches_overclaim">proof</a>.</li><li>((1 = 1) ∧ (1 ≠ 1)) → False — <a href="/theorem/disputed_contradiction_audit_detects_liar">proof</a>.</li><li>((2 * 5 = 10) ∧ (10 / 2 = 5)) — <a href="/theorem/disputed_audit_receipt_open">proof</a>.</li><li>((List.range 3).length = 3) ∧ ((1 = 1) ∧ (2 ≠ 3)) — <a href="/theorem/disputed_all_topics_computable">proof</a>.</li></ul><h2 id="provenance" tabindex="-1">Provenance <a class="header-anchor" href="#provenance" aria-label="Permalink to “Provenance”">​</a></h2><p>These 15 proofs fold, order-invariant, to the receipt <code>65ff330c-4a0b-859f-a5b5-ec542ea0880b</code> — recompute it from the same ledger and it returns. The note itself content-addresses to a uuid, so any edit is visible. Writing descends from reading: this note holds only what the proofs it links already sealed, and it was audited by uuidna&#39;s own honesty gate before it was published — a sentence that overreached a proof would have been refused, not shipped.</p><p>Source · <a href="https://github.com/uuidna/uuidna/blob/main/lean/DisputedTopics.lean" target="_blank" rel="noreferrer">lean/DisputedTopics.lean</a> · <a href="/theorems">all theorems</a></p><hr><p><strong>Audited before published</strong> · this note passed uuidna&#39;s honesty gate at build time — every claim above links the proof that seals it. Content-address <code>c713c867</code> · proofs fold to receipt <code>65ff330c</code> (the handles; the full uuids are in this page&#39;s meta, recomputable) · 15 sealed theorems.</p><p><a href="/publications">All publications</a> · <a href="/theorems">All theorems</a> · <a href="/trials">How auditing works</a></p>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};